referenceSolutions.javascript:
export function solve(text, query) {
  const ranges = [];
  if (!query.length) return ranges;
  for (let i = 0; i + query.length <= text.length; i++)
    if (text.slice(i, i + query.length) === query) ranges.push([i, i + query.length]);
  return ranges;
}

